Analyze this Observer design pattern implementation. What will happen when notify() is called?

interface Observer { void update(String message); }
class EmailAlert implements Observer {
    public void update(String message) { System.out.println("Email: " + message); }
}

class NewsPublisher {
    private List<Observer> observers = new ArrayList<>();
    public void addObserver(Observer obs) { observers.add(obs); }
    public void notify(String news) {
        for (Observer obs : observers) obs.update(news);
    }
}

NewsPublisher publisher = new NewsPublisher();
publisher.addObserver(new EmailAlert());
publisher.notify("Breaking News");

