In this Observer pattern design, what will be printed?

interface Observer { void update(int value); }
class Display implements Observer {
    private String name;
    public Display(String name) { this.name = name; }
    public void update(int value) { System.out.println(name + ": " + value); }
}

class Counter {
    private List<Observer> observers = new ArrayList<>();
    private int count = 0;
    public void addObserver(Observer obs) { observers.add(obs); }
    public void increment() {
        count++;
        observers.forEach(obs -> obs.update(count));
    }
}

